sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Trade Task and Trade task clean up
    var count1 = 0;
    var tc = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
    tc.addEncodedQuery('financial_object.u_idLIKEATF');
    tc.query();

    while (tc.next()) {
        var tcn = tc.sys_id;
        var tt = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        tt.addQuery('parent', '=', tcn);
        //tt.addEncodedQuery('parent=tcn');
        tt.deleteMultiple();
        tc.deleteRecord();
        count1 = count1 + 1;


    }

    //HSBC Trade cleanup
    var count = 0;
    var tR = new GlideRecord('x_hsb11_hsbc_mss_t_hsbc_trade');
    tR.addEncodedQuery('u_idLIKEATF');
    tR.query();

    while (tR.next()) {
        tR.deleteRecord();
        //gs.info("trade sysi id" + tR.u_id);
        count = count + 1;
    }



    //Business process Instance cleanup

    var bpr = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_instance');
    bpr.addEncodedQuery('financial_object_recordLIKEATF');
    bpr.query();
    bpr.deleteMultiple();

    var bpr1 = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_instance');
    bpr1.addEncodedQuery('messageidLIKEATF');
    bpr1.query();
    bpr1.deleteMultiple();



    //Event ibound set to ignored for the processing ones.
    //Ignored

    var evinb = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
    evinb.addEncodedQuery('processing_statusINProcessing');
    evinb.query();
    //while(evinb.next())
    {
        evinb.processing_status = 'Ignored';
        evinb.updateMultiple();
    }

    // Event inbound clean up
    var evinb1 = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
    evinb1.addEncodedQuery('objectidLIKEATF');
    evinb1.query();
    evinb1.deleteMultiple();


    var evinb2 = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
    evinb2.addEncodedQuery('messageidLIKEATF');
    evinb2.query();
    evinb2.deleteMultiple();








})(current, previous);
